package office;

public class Switch {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
    String name = "Anush";
    switch(name) {
    case "Vikas": {
    	System.out.println("Vikas");
       break;  
    }
    case "Chirag": {
    	System.out.println("Chirag");
    	break;
    }
    case "Anush": {
    	System.out.println("Anush");
    //   break; 
    }
    case "Vikass": {
    	System.out.println("Vikass");
    //   break;  
    }
    case "Chiragg": {
    	System.out.println("Chiragg");
    //	break;
    }
    default : {
    	System.out.println("Not a matching name");
    }
    }
    
		
		
		
		
		
	}

}
